const LIST_ID = 2 // your Brevo list id
const u = msg.data.user ?? {}
if (!u.email) continue
if (msg.event === 'member.joined') {
  const [first, ...rest] = (u.name ?? '').trim().split(/\s+/)
  out.push({ json: { method: 'POST', url: 'https://api.brevo.com/v3/contacts', body: { email: u.email, attributes: { FIRSTNAME: first ?? '', LASTNAME: rest.join(' ') }, listIds: [LIST_ID], updateEnabled: true } } })
} else {
  out.push({ json: { method: 'POST', url: `https://api.brevo.com/v3/contacts/lists/${LIST_ID}/contacts/remove`, body: { emails: [u.email] } } })
}
